        if isinstance(a,list): rels+=a
    except Exception: pass
for r in sorted(rels,key=lambda r:r['published_at'] or ''):
    if '2024-06'<=(r['published_at'] or '')<'2024-09-05':
        for l in (r['body'] or '').splitlines():
            if 'dsp-ant' in l or 'mcp' in l.lower() or 'protocol' in l.lower(): print(r['tag_name'],l[:250])
    if r['tag_name'] in ('v0.152.0-pre','v0.152.3'): print('##',r['tag_name'],r['published_at'],r['html_url'])
"

