cat > /tmp/fceval-m3-t1-wcrsltvn/scripts/jb.py <<'EOF'
import json,glob,re,datetime,sys
u={}
for f in glob.glob(sys.argv[1]+'/p*.json'):
    try:
        a=json.loads(json.load(open(f))['rawHtml'])
        for x in a: u[x['id']]=x
    except Exception as e: print('err',f,e)
L=sorted(u.values(),key=lambda x:int(x['cdate']))
d=lambda x:datetime.datetime.utcfromtimestamp(int(x['cdate'])/1000).strftime('%Y-%m-%d %H:%M')
print(len(L),d(L[0]),d(L[-1]))
p=re.compile(r'\bMCP\b|model context protocol',re.I)
n=0
for x in L:
    if p.search(x.get('notes') or ''):
        n+=1
        print('==',x['version'],d(x),x.get('channel'),'https://plugins.jetbrains.com'+x['link'],x.get('since'),x.get('until'))
        if n<=3:
            for l in x['notes'].splitlines():
                if p.search(l): print('   ',l.strip()[:300])
        if n>8: break
EOF
